1	/**
2	 * SFCC-270 (plan step 2.2). Covers:
3	 *   - item-image.tsx: a caller-supplied `width`/`mr` must win over the Zimmermann default
4	 *     (item-variant.css.ts's `image` part) — this is exactly what order-summary/index.jsx's
5	 *     (base, not-yet-overridden) `<CartItemVariantImage width="80px" mr={2} />` depends on.
6	 *   - item-name.tsx: a caller-supplied `color` must win over the Zimmermann default — the bug
7	 *     fix at this step (base had the spread BEFORE the explicit `color`, silently discarding
8	 *     any caller value).
9	 *   - item-attributes.tsx (round 2 rework): the pre-existing per-key rendering path — used
10	 *     unmodified today by order-summary, wishlist/checkout partials, account/order-detail, and
11	 *     the confirmation page — still renders correctly now that it sits behind this build's new
12	 *     `!combineAttributeValues &&` guard.
13	 *   - item-price.tsx (round 2 rework, should-fix): the `isDesktop`-gated PricePerItem
14	 *     positioning, the `isOnSale`-driven stack spacing, and the `price` recipe's textStyle.
15	 *
16	 * `useMultiSite` is mocked, not provided via a real MultiSiteProvider: item-name.tsx's <Link>
17	 * calls it internally, and its real dependency chain (`@salesforce/retail-react-app/app/
18	 * contexts`) fails to parse under Vitest's Vite transform — same mock, same reasoning, as
19	 * header/rightBar/index.test.tsx's own `vi.mock('.../use-multi-site', ...)`.
20	 *
21	 * item-attributes.tsx/item-price.tsx pull in several more hooks that need the same treatment,
22	 * all following that identical established pattern (mock the smallest surface, per
23	 * .claude/rules/testing.md): `useCurrency` (full replacement — this file's render tree never
24	 * needs the real `useDerivedProduct` also exported from that barrel, unlike
25	 * product-item/index.test.tsx, so no `vi.importActual` juggling is needed here), a real-network
26	 * `useCurrentBasket`, `PromoPopover` (imports the base icons barrel, throws under Vitest per
27	 * testing.md's documented ZimmIcon gap), and `usePromotions`/`useProducts`/`useProduct` from
28	 * `@salesforce/commerce-sdk-react`. `useBreakpointValue` is mocked directly (from `@chakra-ui/react`,
29	 * which `shared/ui`'s own `useBreakpointValue` module just re-exports) so item-price.tsx's
30	 * `isDesktop` resolves to an exact, per-test value — the same pattern
31	 * zimmSizeSelector/index.test.tsx already establishes, rather than fighting Chakra's internal
32	 * breakpoint-matching media queries via a `window.matchMedia` mock.
33	 */
34	import React from 'react';
35	import { describe, test, expect, vi, beforeEach } from 'vitest';
36	import { render, screen } from '@testing-library/react';
37	import { ChakraProvider, useBreakpointValue } from '@chakra-ui/react';
38	import { IntlProvider } from 'react-intl';
39	import { MemoryRouter } from 'react-router-dom';
40	import theme from 'app/theme';
41	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
42	import ItemVariantProvider from '.';
43	import CartItemVariantImage from './item-image';
44	import CartItemVariantName from './item-name';
45	import CartItemVariantAttributes from './item-attributes';
46	import CartItemVariantPrice from './item-price';
47	
48	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
49	  default: vi.fn(),
50	}));
51	
52	vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
53	  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
54	}));
55	
56	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
57	  useCurrentBasket: () => ({ data: undefined }),
58	}));
59	
60	vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
61	  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
62	}));
63	
64	vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
65	  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
66	  return {
67	    ...actual,
68	    usePromotions: () => ({ data: undefined }),
69	    useProducts: () => ({ data: undefined, isLoading: false }),
70	    useProduct: () => ({ data: undefined, isLoading: false }),
71	  };
72	});
73	
74	vi.mock('@chakra-ui/react', async (importOriginal) => {
75	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
76	  return {
77	    ...actual,
78	    useBreakpointValue: vi.fn(),
79	  };
80	});
81	
82	const mockUseMultiSite = vi.mocked(useMultiSite);
83	const mockUseBreakpointValue = vi.mocked(useBreakpointValue);
84	
85	// ChakraProvider with this project's own theme is required, not optional here — without it,
86	// `textStyle="productNames"` resolves against Chakra's default (empty) textStyles, and
87	// `useBreakpointValue` (item-price.tsx, exercised transitively were this file to render it)
88	// throws outright reading `theme.breakpoints` off an undefined theme. Same setup zimmButton's
89	// own test uses.
90	const renderWithProviders = (ui: React.ReactElement) =>
91	  render(
92	    <ChakraProvider theme={theme}>
93	      <MemoryRouter>
94	        <IntlProvider locale="en-AU" defaultLocale="en-AU">
95	          {ui}
96	        </IntlProvider>
97	      </MemoryRouter>
98	    </ChakraProvider>,
99	  );
100	
101	const baseVariant = {
102	  id: 'variant-1',
103	  productName: 'Lilac Sand Dress',
104	  imageGroups: [
105	    {
106	      viewType: 'small',
107	      images: [{ alt: 'Lilac Sand Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
108	    },
109	  ],
110	};
111	
112	describe('item-variant', () => {
113	  beforeEach(() => {
114	    mockUseMultiSite.mockReturnValue({
115	      site: { id: 'ZimmermannAU' },
116	      buildUrl: (path: string) => path,
117	    });
118	  });
119	
120	  describe('CartItemVariantImage (item-image) — defaults-then-spread', () => {
121	    test('a caller-supplied width wins over the Zimmermann default', () => {
122	      const { container } = renderWithProviders(
123	        <ItemVariantProvider variant={baseVariant}>
124	          <CartItemVariantImage width="321px" />
125	        </ItemVariantProvider>,
126	      );
127	      const box = container.firstElementChild as HTMLElement;
128	      expect(box).toHaveStyle({ width: '321px' });
129	    });
130	
131	    test('a caller-supplied mr is applied (the exact regression that would break order-summary)', () => {
132	      const { container } = renderWithProviders(
133	        <ItemVariantProvider variant={baseVariant}>
134	          <CartItemVariantImage mr="37px" />
135	        </ItemVariantProvider>,
136	      );
137	      const box = container.firstElementChild as HTMLElement;
138	      expect(box).toHaveStyle({ marginRight: '37px' });
139	    });
